  x✝.divModByMonicAux x✝² =
    match x✝, x✝¹, x✝² with
    | p, q, hq =>
      if h : q.degree ≤ p.degree ∧ p ≠ 0 then
        have z := Polynomial.C p.leadingCoeff * Polynomial.X ^ (p.natDegree - q.natDegree);
